// Completed tournaments — hardcoded so Firestore is never needed to show past results.
// Add an entry here (hardcoded: true) whenever a tournament is finalized.
// Live/upcoming tournaments are still fetched from Firestore and do NOT appear here.
const TOURNAMENT_REGISTRY = [
  { id: 'masters-2026',   major: 'masters',  year: 2026, status: 'final', hardcoded: true },
  { id: 'pga-2026',       major: 'pga',      year: 2026, status: 'final', hardcoded: true },
  { id: 'us-open-2026',   major: 'us-open',  year: 2026, status: 'final', hardcoded: true },
];

// â”€â”€â”€ Entry point â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
export async function loadStandings() {
  try {
    await loadAllTournaments();
  } catch (err) {
    console.error('Failed to load tournament list:', err);
    showLoading(false);
    const noData = document.getElementById('noDataMsg');
    if (noData) {
      noData.textContent = 'Unable to load standings — please refresh the page.';
      noData.classList.remove('hidden');
    }
    return;
  }

  // Auto-load best Masters tournament (open > locked > final, newest year)
  const mastersList = tournamentsByMajor['masters'] || [];
  if (mastersList.length) {
    currentTournamentId = mastersList[0].id;
    setYearTabActive('masters', mastersList[0].year);
    await loadTournamentData(mastersList[0].id);
  }

  // Pre-load PGA in background so picks are ready when user navigates to PGA tab
  const pgaList = tournamentsByMajor['pga'] || [];
  if (pgaList.length) {
    pgaCurrentTournamentId = pgaList[0].id;
    setYearTabActive('pga', pgaList[0].year);
    loadPgaTournamentData(pgaList[0].id);
  }

  // Pre-load US Open and The Open in background (pool tab + season leaderboard)
  const usOpenList = tournamentsByMajor['usopen'] || [];
  if (usOpenList.length) {
    usOpenCurrentTournamentId = usOpenList[0].id;
    setYearTabActive('usopen', usOpenList[0].year);
    loadUsOpenTournamentData(usOpenList[0].id);
    loadUsOpenScoreboard();
  }
  const theOpenList = tournamentsByMajor['theopen'] || [];
  if (theOpenList.length) {
    theOpenCurrentTournamentId = theOpenList[0].id;
    setYearTabActive('theopen', theOpenList[0].year);
    loadTheOpenTournamentData(theOpenList[0].id);
  }

  const searchInput = document.getElementById('standingsSearch');
  if (searchInput) {
    searchInput.addEventListener('input', () => filterTable(searchInput.value));
  }
}

// â”€â”€â”€ Load and group all tournaments by major â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
async function loadAllTournaments() {
  // Seed immediately from registry — no Firestore needed for hardcoded entries.
  // Past results are always available even if Firestore is slow or offline.
  tournamentsByMajor = {};
  for (const t of TOURNAMENT_REGISTRY) {
    const key = normalizeMajorKey(t.major);
    if (!tournamentsByMajor[key]) tournamentsByMajor[key] = [];
    tournamentsByMajor[key].push(t);
  }

  // Fetch live/upcoming tournaments from Firestore, skipping any already in registry.
  try {
    const db = getDb();
    const timeout = new Promise((_, reject) =>
      setTimeout(() => reject(new Error('Firestore timed out')), 12000)
    );
    const snap = await Promise.race([getDocs(collection(db, 'tournaments')), timeout]);
    const registryIds = new Set(TOURNAMENT_REGISTRY.map(t => t.id));
    snap.forEach(d => {
      if (registryIds.has(d.id)) return; // registry entry takes precedence
      const t = { id: d.id, ...d.data() };
      const key = normalizeMajorKey(t.major);
      if (!tournamentsByMajor[key]) tournamentsByMajor[key] = [];
      tournamentsByMajor[key].push(t);
    });
  } catch (err) {
    console.warn('Firestore unavailable — showing hardcoded results only:', err.message);
  }

  const order = { open: 0, locked: 1, final: 2 };
  for (const key of Object.keys(tournamentsByMajor)) {
    tournamentsByMajor[key].sort((a, b) =>
      (order[a.status] ?? 3) - (order[b.status] ?? 3) || b.year - a.year
    );
  }

  for (const [major, ts] of Object.entries(tournamentsByMajor)) {
    markYearTabsAvailable(major, ts.map(t => t.year));
  }
}

function normalizeMajorKey(major) {
  if (!major) return 'masters';
  const m = major.toLowerCase();
  if (m.includes('master')) return 'masters';
  if (m.includes('pga')) return 'pga';
  if (m.includes('us') || m.includes('u.s')) return 'usopen';
  if (m.includes('open')) return 'theopen';
  return major;
}

// â”€â”€â”€ Year tab helpers â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
function setYearTabActive(major, year) {
  const bar = document.getElementById(major + '-year-tabs');
  if (!bar) return;
  bar.querySelectorAll('.year-tab').forEach(btn => {
    btn.classList.toggle('active', parseInt(btn.dataset.year) === year);
  });
}

function markYearTabsAvailable(major, years) {
  const bar = document.getElementById(major + '-year-tabs');
  if (!bar) return;
  // 2025 hardcoded scoreboard data available for Masters, PGA, US Open, and The Open
  const hardcodedYears = major === 'masters' ? [2025] : (major === 'pga' || major === 'usopen' || major === 'theopen') ? [2025] : [];
  bar.querySelectorAll('.year-tab').forEach(btn => {
    const y = parseInt(btn.dataset.year);
    const available = years.includes(y) || hardcodedYears.includes(y);
    btn.disabled = !available;
    btn.classList.toggle('year-tab-empty', !available);
  });
}

export function switchMajorYear(major, year) {
  const ts = tournamentsByMajor[major] || [];
  const t = ts.find(x => x.year === year);
  setYearTabActive(major, year);
  if (t) {
    if (major === 'masters') {
      currentTournamentId = t.id;
      loadTournamentData(t.id);
      restoreMastersPoolPanels();
    }
    // Other majors handle their own live loading in the major-specific blocks below
  } else {
    if (major === 'masters') {
      clearMastersPoolPanels();
    }
    const majorPanel = document.getElementById('panel-' + major);
    if (majorPanel) {
      majorPanel.querySelectorAll('.inner-panel').forEach(p => {
        p.classList.remove('inner-panel-active');
        p.classList.add('hidden');
      });
      majorPanel.querySelectorAll('.inner-tab').forEach(btn => btn.classList.remove('active'));
      if ((major === 'masters' && year === 2025) || (major === 'pga' && year === 2025)) {
        // Total tab has hardcoded 2025 standings
        const totalPanel = document.getElementById(major + '-total');
        if (totalPanel) { totalPanel.classList.remove('hidden'); totalPanel.classList.add('inner-panel-active'); }
        const totalBtn = majorPanel.querySelector('.inner-tab[data-inner="total"]');
        if (totalBtn) totalBtn.classList.add('active');
      } else {
        // No pool data \u2014 jump to scoreboard tab
        const sbPanel = document.getElementById(major + '-scoreboard');
        if (sbPanel) { sbPanel.classList.remove('hidden'); sbPanel.classList.add('inner-panel-active'); }
        const sbBtn = majorPanel.querySelector('.inner-tab[data-inner="scoreboard"]');
        if (sbBtn) sbBtn.classList.add('active');
      }
    }
  }
  if (major === 'masters') {
    mastersActiveYear = year;
    loadMastersScoreboard();
    if (year === 2025) { loadMasters2025TotalStandings(); loadMasters2025Round1Standings(); loadMasters2025Round2Standings(); loadMasters2025Round3Standings(); loadMasters2025Round4Standings(); loadMasters2025Payouts(); }
  }
  if (major === 'pga') {
    pgaActiveYear = year;
    loadPgaScoreboard();
    if (year === 2025) { loadPga2025TotalStandings(); loadPga2025Round1Standings(); loadPga2025Round2Standings(); loadPga2025Round3Standings(); loadPga2025Round4Standings(); loadPga2025Payouts(); }
    else {
      // Reset inner tab state so 2025 panels don't stay visible when switching to 2026
      const pgaPanel = document.getElementById('panel-pga');
      if (pgaPanel) {
        pgaPanel.querySelectorAll('.inner-panel').forEach(p => { p.classList.remove('inner-panel-active'); p.classList.add('hidden'); });
        pgaPanel.querySelectorAll('.inner-tab').forEach(btn => btn.classList.remove('active'));
        const totalPanel = document.getElementById('pga-total');
        if (totalPanel) { totalPanel.classList.remove('hidden'); totalPanel.classList.add('inner-panel-active'); }
        const totalBtn = pgaPanel.querySelector('.inner-tab[data-inner="total"]');
        if (totalBtn) totalBtn.classList.add('active');
      }
      clearPgaPoolPanels();
      if (t) {
        loadPgaTournamentData(t.id);
      } else {
        // No tournament in Firestore \u2014 show message instead of frozen spinner
        const loadingEl = document.getElementById('pgaLoadingMsg');
        const noDataEl  = document.getElementById('pgaNoDataMsg');
        if (loadingEl) loadingEl.classList.add('hidden');
        if (noDataEl) {
          noDataEl.textContent = 'PGA Championship 2026 tournament not found. Check admin setup.';
          noDataEl.classList.remove('hidden');
        }
      }
    }
  }
  if (major === 'usopen') {
    usOpenActiveYear = year;
    loadUsOpenScoreboard();
    if (year === 2025) {
      loadUsOpen2025TotalStandings();
      loadUsOpen2025Round1Standings();
      loadUsOpen2025Round2Standings();
      loadUsOpen2025Round3Standings();
      loadUsOpen2025Round4Standings();
      loadUsOpen2025Payouts();
      const usOpenPanel2025 = document.getElementById('panel-usopen');
      if (usOpenPanel2025) {
        usOpenPanel2025.querySelectorAll('.inner-panel').forEach(p => { p.classList.remove('inner-panel-active'); p.classList.add('hidden'); });
        usOpenPanel2025.querySelectorAll('.inner-tab').forEach(btn => btn.classList.remove('active'));
        const totalPanel = document.getElementById('usopen-total');
        if (totalPanel) { totalPanel.classList.remove('hidden'); totalPanel.classList.add('inner-panel-active'); }
        const totalBtn = usOpenPanel2025.querySelector('.inner-tab[data-inner="total"]');
        if (totalBtn) totalBtn.classList.add('active');
      }
    } else {
      // Reset pool tab panels so 2025 data doesn't linger
      clearUsOpenPoolPanels();
      const usOpenPanel = document.getElementById('panel-usopen');
      if (usOpenPanel) {
        usOpenPanel.querySelectorAll('.inner-panel').forEach(p => { p.classList.remove('inner-panel-active'); p.classList.add('hidden'); });
        usOpenPanel.querySelectorAll('.inner-tab').forEach(btn => btn.classList.remove('active'));
        const totalPanel = document.getElementById('usopen-total');
        if (totalPanel) { totalPanel.classList.remove('hidden'); totalPanel.classList.add('inner-panel-active'); }
        const totalBtn = usOpenPanel.querySelector('.inner-tab[data-inner="total"]');
        if (totalBtn) totalBtn.classList.add('active');
      }
      if (t) {
        loadUsOpenTournamentData(t.id);
      } else {
        const loadingEl = document.getElementById('usOpenLoadingMsg');
        const noDataEl  = document.getElementById('usOpenNoDataMsg');
        if (loadingEl) loadingEl.classList.add('hidden');
        if (noDataEl) {
          noDataEl.textContent = 'U.S. Open 2026 tournament not found. Check admin setup.';
          noDataEl.classList.remove('hidden');
        }
      }
    }
  }
  if (major === 'theopen') {
    theOpenActiveYear = year;
    loadTheOpenScoreboard();
    if (year === 2025) {
      loadTheOpen2025TotalStandings();
      loadTheOpen2025Round1Standings();
      loadTheOpen2025Round2Standings();
      loadTheOpen2025Round3Standings();
      loadTheOpen2025Round4Standings();
      loadTheOpen2025Payouts();
      const theOpenPanel2025 = document.getElementById('panel-theopen');
      if (theOpenPanel2025) {
        theOpenPanel2025.querySelectorAll('.inner-panel').forEach(p => { p.classList.remove('inner-panel-active'); p.classList.add('hidden'); });
        theOpenPanel2025.querySelectorAll('.inner-tab').forEach(btn => btn.classList.remove('active'));
        const totalPanel = document.getElementById('theopen-total');
        if (totalPanel) { totalPanel.classList.remove('hidden'); totalPanel.classList.add('inner-panel-active'); }
        const totalBtn = theOpenPanel2025.querySelector('.inner-tab[data-inner="total"]');
        if (totalBtn) totalBtn.classList.add('active');
      }
    } else {
      const theOpenPanel = document.getElementById('panel-theopen');
      if (theOpenPanel) {
        theOpenPanel.querySelectorAll('.inner-panel').forEach(p => { p.classList.remove('inner-panel-active'); p.classList.add('hidden'); });
        theOpenPanel.querySelectorAll('.inner-tab').forEach(btn => btn.classList.remove('active'));
        const totalPanel = document.getElementById('theopen-total');
        if (totalPanel) { totalPanel.classList.remove('hidden'); totalPanel.classList.add('inner-panel-active'); }
        const totalBtn = theOpenPanel.querySelector('.inner-tab[data-inner="total"]');
        if (totalBtn) totalBtn.classList.add('active');
      }
      if (t) {
        loadTheOpenTournamentData(t.id);
      } else {
        const loadingEl = document.getElementById('theOpenLoadingMsg');
        const noDataEl  = document.getElementById('theOpenNoDataMsg');
        if (loadingEl) loadingEl.classList.add('hidden');
        if (noDataEl) {
          noDataEl.textContent = 'The Open Championship 2026 tournament not found. Check admin setup.';
          noDataEl.classList.remove('hidden');
        }
      }
    }
  }
}

function clearMastersPoolPanels() {
  const placeholder = '<div class="coming-soon">2025 Masters pool data coming soon.</div>';

  // Total tab \u2014 clear table, show placeholder message
  const table = document.getElementById('standingsTable');
  const body  = document.getElementById('standingsBody');
  const loading = document.getElementById('loadingMsg');
  const noData  = document.getElementById('noDataMsg');
  if (table)   table.classList.add('hidden');
  if (body)    body.innerHTML = '';
  if (loading) loading.classList.add('hidden');
  if (noData)  { noData.textContent = '2025 Masters pool data coming soon.'; noData.classList.remove('hidden'); }

  // Round tabs
  ['masters-day1','masters-day2','masters-day3','masters-day4'].forEach(id => {
    const el = document.getElementById(id);
    if (el) el.innerHTML = placeholder;
  });

  // Final Payouts \u2014 save existing HTML then replace
  const fp = document.getElementById('masters-finalpayouts');
  if (fp) {
    if (!savedMastersFpHtml) savedMastersFpHtml = fp.innerHTML;
    fp.innerHTML = placeholder;
  }
}

function restoreMastersPoolPanels() {
  // noDataMsg back to default hidden state
  const noData = document.getElementById('noDataMsg');
  if (noData) { noData.textContent = 'No picks found for this tournament.'; noData.classList.add('hidden'); }

  // Restore round tabs
  loadRound1Standings();
  loadRound2Standings();
  loadRound3Standings();
  loadRound4Standings();

  // Restore Final Payouts HTML and re-wire dynamic content
  const fp = document.getElementById('masters-finalpayouts');
  if (fp && savedMastersFpHtml) {
    fp.innerHTML = savedMastersFpHtml;
    loadMastersPayouts();
  }
}

