// â”€â”€â”€ Load full tournament data â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
async function loadTournamentData(tournamentId) {
  showLoading(true);
  clearInterval(refreshTimer);

  try {
    const registryEntry = TOURNAMENT_REGISTRY.find(t => t.id === tournamentId && t.hardcoded);
    let tournament;
    if (registryEntry) {
      tournament = registryEntry;
    } else {
      const db = getDb();
      const tSnap = await getDoc(doc(db, 'tournaments', tournamentId));
      if (!tSnap.exists()) { showLoading(false); return; }
      tournament = { id: tSnap.id, ...tSnap.data() };
    }
    currentTournamentStatus = tournament.status;

    renderStatusLabel(tournament);
    renderCountdown(tournament);
    renderPrizes(tournament);
    updateRefreshButton(tournament);

    // Hide standings while picks are still open \u2014 prevents entrants copying each other
    if (tournament.status === 'open') {
      const deadline = tournament.pickDeadline ? new Date(tournament.pickDeadline) : null;
      if (!deadline || Date.now() < deadline.getTime()) {
        const noData = document.getElementById('noDataMsg');
        const revealTime = deadline ? deadline.toLocaleString() : 'picks lock';
        noData.textContent = `Standings are hidden while picks are open. Check back after ${revealTime}.`;
        noData.classList.remove('hidden');
        showLoading(false);
        return;
      }
    }

    // Masters 2026 Total standings are finalized and hardcoded \u2014 skip live ESPN fetch
    if (tournament.year === 2026 && normalizeMajorKey(tournament.major) === 'masters') {
      renderTable(MASTERS_2026_TOTAL, {});
      updateLastUpdated();
      showLoading(false);
      return;
    }

    const picksSnap = await getDocs(
      query(collection(db, 'picks'), where('tournamentId', '==', tournamentId))
    );
    const picks = [];
    picksSnap.forEach(d => picks.push({ id: d.id, ...d.data() }));

    const scoresMap = await fetchOrRefreshScores(tournament);
    cachedScoresMap = scoresMap;
    cachedResults = calculateStandings(picks, scoresMap, tournament.mcPenalty ?? 20);
    renderTable(cachedResults, scoresMap);
    updateLastUpdated();
    showLoading(false);

    if (tournament.status === 'locked') {
      refreshTimer = setInterval(() => refreshScores(tournament), REFRESH_INTERVAL_MS);
    }
  } catch (err) {
    console.error('Error loading standings:', err);
    showLoading(false);
    document.getElementById('noDataMsg').classList.remove('hidden');
  }
}

function updateRefreshButton(tournament) {
  const btn = document.getElementById('refreshBtn');
  if (!btn) return;
  const isFinal = tournament.status === 'final';
  btn.disabled = isFinal;
  btn.title = isFinal ? 'Tournament is final \u2014 live updates are disabled' : '';
  btn.classList.toggle('btn-disabled', isFinal);
}

// â”€â”€â”€ ESPN API: fetch scores, cache in Firestore â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
async function fetchOrRefreshScores(tournament) {
  const db = getDb();
  const scoreDoc = doc(db, 'scores', tournament.id);
  const scoreSnap = await getDoc(scoreDoc);

  if (scoreSnap.exists()) {
    const data = scoreSnap.data();
    const lastUpdated = data._lastUpdated?.toMillis?.() ?? 0;
    const age = Date.now() - lastUpdated;
    // Also re-fetch if cache pre-dates the per-round schema (no r1 fields)
    const hasRoundData = Object.values(data).some(v => v && typeof v === 'object' && 'r1' in v);
    if ((tournament.status !== 'locked' || age < REFRESH_INTERVAL_MS) && hasRoundData) {
      const { _lastUpdated, ...scores } = data;
      return scores;
    }
  }

  if (!tournament.espnEventId) {
    if (scoreSnap.exists()) { const { _lastUpdated, ...s } = scoreSnap.data(); return s; }
    return {};
  }
  const freshScores = await fetchEspnScores(tournament.espnEventId);
  if (Object.keys(freshScores).length) {
    try { await setDoc(scoreDoc, { ...freshScores, _lastUpdated: new Date() }); } catch (e) { console.warn('Score cache write failed:', e.message); }
    return freshScores;
  }
  // ESPN returned empty — fall back to stale Firestore cache rather than returning {}
  if (scoreSnap.exists()) {
    const { _lastUpdated, ...staleScores } = scoreSnap.data();
    if (Object.keys(staleScores).length) return staleScores;
  }
  return freshScores;
}

async function fetchEspnScores(espnEventId) {
  try {
    const url = `https://site.api.espn.com/apis/site/v2/sports/golf/leaderboard?event=${espnEventId}`;
    const ac = new AbortController();
    const timeout = setTimeout(() => ac.abort(), 10000);
    let res;
    try {
      res = await fetch(url, { signal: ac.signal });
    } finally {
      clearTimeout(timeout);
    }
    if (!res.ok) return {};
    const data = await res.json();
    return parseEspnLeaderboard(data);
  } catch {
    return {};
  }
}

function parseEspnLeaderboard(data) {
  const scores = {};
  const competitors = data?.events?.[0]?.competitions?.[0]?.competitors ?? [];
  for (const c of competitors) {
    const name = c.athlete?.displayName;
    if (!name) continue;

    // Compute score from completed round linescores \u2014 ESPN's total field shows "E" mid-round
    const ls = c.linescores ?? [];
    const rounds = [1,2,3,4].map(p => {
      const r = ls.find(l => l.period === p);
      if (!r) return null;
      const dv = r.displayValue;
      if (!dv || dv === '--' || dv === '-') return null;
      if (dv === 'E') return 0;
      const v = parseFloat(dv);
      return isNaN(v) ? null : v;
    });
    const completed = rounds.filter(r => r !== null);
    const scoreStr = c.score?.displayValue ?? 'E';
    const score = completed.length > 0
      ? completed.reduce((sum, r) => sum + r, 0)
      : (scoreStr === 'E' ? 0 : (parseFloat(scoreStr) || 0));

    const status = c.status?.type?.name?.toLowerCase() ?? 'active';
    let normalizedStatus = 'active';
    if (status.includes('cut')) normalizedStatus = 'cut';
    else if (status.includes('wd') || status.includes('withdrew')) normalizedStatus = 'wd';

    scores[name] = {
      score,
      r1: rounds[0], r2: rounds[1], r3: rounds[2], r4: rounds[3],
      position: c.status?.position?.displayName ?? '-',
      status: normalizedStatus
    };
  }
  return scores;
}

// â”€â”€â”€ Name reconciliation helpers â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
function normalizeName(name) {
  return (name || '').toLowerCase()
    // \u escapes are ASCII-only and survive any future re-encoding
    .replace(/\u00f8/g, 'o').replace(/\u00f0/g, 'd').replace(/\u00fe/g, 'th').replace(/\u0142/g, 'l').replace(/\u00e6/g, 'ae')
    .normalize('NFD').replace(/[\u0300-\u036F]/g, '')
    .replace(/[^a-z\s]/g, '').replace(/\s+/g, ' ').trim();
}

function reconcilePickNames(picks, scoresMap) {
  const normalizedLookup = {};
  for (const espnName of Object.keys(scoresMap)) {
    normalizedLookup[normalizeName(espnName)] = espnName;
  }
  const remapped = [];
  const result = picks.map(pick => {
    const fixed = { ...pick };
    for (const t of ['t1','t2','t3','t4','t5','t6']) {
      const golfer = pick[t];
      if (golfer && !scoresMap[golfer]) {
        const espnName = normalizedLookup[normalizeName(golfer)];
        if (espnName) { fixed[t] = espnName; remapped.push(`"${golfer}" â†' "${espnName}"`); }
      }
    }
    return fixed;
  });
  if (remapped.length) console.info('PGA name auto-reconciled:', [...new Set(remapped)]);
  return result;
}

function buildRoundScoresMap(scoresMap, round) {
  const key = `r${round}`;
  const map = {};
  for (const [name, g] of Object.entries(scoresMap)) {
    const isCutWd = g.status === 'cut' || g.status === 'wd';
    const rScore = g[key] ?? null;
    // Cut/WD players with no linescore for this round (R3/R4) get the per-round penalty (+10)
    const score = (isCutWd && rScore === null) ? 10 : (rScore !== null ? rScore : 0);
    map[name] = { score, status: 'active', position: g.position };
  }
  return map;
}

function renderPgaRoundPanel(round, results) {
  const panel = document.getElementById(`pga-day${round}`);
  if (!panel) return;
  if (!results.length) {
    panel.innerHTML = '<div class="coming-soon">No round data available yet.</div>';
    return;
  }

  // Build panel HTML skeleton with search bar, sortable thead, and named tbody/table ids
  panel.innerHTML = `
    <div class="search-bar">
      <input type="text" id="pgaRoundSearch${round}" class="standings-search" placeholder="Search entry or player\u2026"
        oninput="(function(q){document.querySelectorAll('#pgaRoundBody${round} tr').forEach(row=>{const e=row.dataset.entry||'';const p=row.dataset.players||'';row.style.display=(!q||e.includes(q)||p.includes(q))?'':'none';})})(this.value.toLowerCase().trim())" />
    </div>
    <div class="table-wrapper">
      <table id="pgaRoundTable${round}" class="standings-table">
        <thead><tr>
          <th class="col-rank sortable" data-sort="rank" onclick="pgaPoolSort('r${round}','rank')">Rank <span class="sort-icon"></span></th>
          <th class="col-name sortable" data-sort="name" onclick="pgaPoolSort('r${round}','name')">Name <span class="sort-icon"></span></th>
          <th class="col-name col-picks-name sortable" data-sort="picksName" onclick="pgaPoolSort('r${round}','picksName')">Picks Name <span class="sort-icon"></span></th>
          <th class="col-total sortable" data-sort="total" onclick="pgaPoolSort('r${round}','total')">R${round} <span class="sort-icon"></span></th>
          <th class="col-tier">Tier 1</th>
          <th class="col-tier">Tier 2</th>
          <th class="col-tier">Tier 3</th>
          <th class="col-tier">Tier 4</th>
          <th class="col-tier">Tier 5</th>
          <th class="col-tier">Tier 6</th>
        </tr></thead>
        <tbody id="pgaRoundBody${round}"></tbody>
      </table>
    </div>`;

  renderPgaPoolRows(`r${round}`, results);
  updatePgaPoolSortHeaders(`r${round}`);
}

async function refreshScores(tournament) {
  const db = getDb();
  const fresh = await fetchEspnScores(tournament.espnEventId);
  if (Object.keys(fresh).length) {
    await setDoc(doc(db, 'scores', tournament.id), { ...fresh, _lastUpdated: new Date() });
    cachedScoresMap = fresh;
    cachedResults = calculateStandings(
      cachedResults.map(r => r.pick),
      fresh,
      tournament.mcPenalty ?? 20
    );
    renderTable(cachedResults, fresh);
    updateLastUpdated();
  }
}

// â”€â”€â”€ Render helpers â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
function renderTable(results, scoresMap) {
  const tbody = document.getElementById('standingsBody');
  const table = document.getElementById('standingsTable');
  const noData = document.getElementById('noDataMsg');

  if (!results.length) {
    table.classList.add('hidden');
    noData.classList.remove('hidden');
    return;
  }

  table.classList.remove('hidden');
  noData.classList.add('hidden');

  tbody.innerHTML = results.map(r => {
    const rankClass = r.rank <= 3 ? `rank-${r.rank}` : '';
    const rankDisplay = r.rank <= 3 ? ['\uD83E\uDD47', '\uD83E\uDD48', '\uD83E\uDD49'][r.rank - 1] : r.rank;
    const totalCls = scoreClass(r.total, null);

    // Live Firestore picks: realName = real name, entrantName = picks name
    // Hardcoded arrays: entrantName = real name, picksName = picks name
    // Strip trailing number suffix in case realName wasn't entered separately
    const rawName   = r.pick.realName  || r.pick.entrantName;
    const realName  = rawName.replace(/ \d+$/, '');
    const picksName = r.pick.picksName || r.pick.entrantName;

    const tierCells = [1,2,3,4,5,6].map(i => {
      const t = r.tierScores[`t${i}`];
      const cls = scoreClass(t.score, t.status);
      const label = t.status === 'cut' ? 'MC' : t.status === 'wd' ? 'WD' : formatScore(t.score, t.status);
      const top4Class = t.isTop4 ? 'top-4-pick' : '';
      return `<td class="col-tier ${top4Class}" title="${t.golfer}"><div class="tier-cell-card"><span class="player-name-cell">${shortName(t.golfer)}</span><small class="score-val ${cls}">${label}</small></div></td>`;
    }).join('');

    const allPlayers = [1,2,3,4,5,6].map(i => r.tierScores[`t${i}`]?.golfer || '').join(' ');

    return `
      <tr data-entry="${escapeHtml(picksName).toLowerCase()} ${escapeHtml(realName).toLowerCase()}" data-players="${escapeHtml(allPlayers).toLowerCase()}">
        <td class="col-rank ${rankClass}">${rankDisplay}</td>
        <td class="col-name">${escapeHtml(realName)}</td>
        <td class="col-name col-picks-name">${escapeHtml(picksName)}</td>
        <td class="col-total"><span class="score-val ${totalCls}">${formatScore(r.total, null)}</span></td>
        ${tierCells}
      </tr>
    `;
  }).join('');

  // Re-apply active search filter after re-render
  const searchInput = document.getElementById('standingsSearch');
  if (searchInput && searchInput.value) filterTable(searchInput.value);
}

function filterTable(query) {
  const q = (query || '').toLowerCase().trim();
  const tbody = document.getElementById('standingsBody');
  if (!tbody) return;
  tbody.querySelectorAll('tr').forEach(row => {
    const entry = row.dataset.entry || '';
    const players = row.dataset.players || '';
    row.style.display = (!q || entry.includes(q) || players.includes(q)) ? '' : 'none';
  });
}

// Default payout split (45/25/15/10/5) used when tournament has no prizePayouts config
const DEFAULT_PAYOUT_SPLIT = [
  { place: 1, pct: 45 },
  { place: 2, pct: 25 },
  { place: 3, pct: 15 },
  { place: 4, pct: 10 },
  { place: 5, pct:  5 },
];

function renderPrizes(tournament) {
  const section = document.getElementById('prizeSection');
  const grid = document.getElementById('prizeGrid');
  if (!tournament.entryFee) { section.classList.add('hidden'); return; }

  const total = tournament.entryFee * (tournament.entryCount ?? 0);
  if (!total) { section.classList.add('hidden'); return; }
  section.classList.remove('hidden');

  const payouts = tournament.prizePayouts ?? DEFAULT_PAYOUT_SPLIT;
  grid.innerHTML = payouts.map(p => {
    const amt = (total * p.pct / 100).toFixed(2).replace(/\.00$/, '');
    return `<div class="prize-item"><strong>$${amt}</strong> \u2014 ${ordinal(p.place)} (${p.pct}%)</div>`;
  }).join('');
}

function renderStatusLabel(tournament) {
  const el = document.getElementById('statusLabel');
  if (!el) return;
  // "Final" is communicated by the "Final Payouts" tab itself \u2014 hide the pill when final
  if (tournament.status === 'final') { el.textContent = ''; el.className = 'status-label inner-tab-status'; return; }
  const labels = { open: 'Picks Open', locked: 'In Progress' };
  const cls    = { open: 'status-open', locked: 'status-locked' };
  el.textContent = labels[tournament.status] ?? tournament.status;
  el.className = `status-label ${cls[tournament.status] ?? ''}`;
}

function renderCountdown(tournament) {
  const el = document.getElementById('lockCountdown');
  if (!tournament.pickDeadline || tournament.status !== 'open') { el.classList.add('hidden'); return; }
  const deadline = new Date(tournament.pickDeadline);

  function update() {
    const diff = deadline - Date.now();
    if (diff <= 0) { el.textContent = 'Picks are now locked'; return; }
    const h = Math.floor(diff / 36e5);
    const m = Math.floor((diff % 36e5) / 6e4);
    el.textContent = `Picks lock in ${h}h ${m}m`;
  }
  update();
  el.classList.remove('hidden');
  setInterval(update, 60000);
}

function updateLastUpdated() {
  const el = document.getElementById('lastUpdated');
  if (el) el.textContent = `Updated ${new Date().toLocaleTimeString()}`;
}

function showLoading(show) {
  document.getElementById('loadingMsg').classList.toggle('hidden', !show);
  if (show) {
    document.getElementById('standingsTable').classList.add('hidden');
    document.getElementById('noDataMsg').classList.add('hidden');
  }
}

// â”€â”€â”€ Sorting â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
export function sortBy(col) {
  if (sortColumn === col) sortAsc = !sortAsc;
  else { sortColumn = col; sortAsc = true; }

  const sorted = [...cachedResults].sort((a, b) => {
    let va, vb;
    if (col === 'rank')  { va = a.rank; vb = b.rank; }
    else if (col === 'total') { va = a.total; vb = b.total; }
    else if (col === 'name')  { va = a.pick.entrantName.toLowerCase(); vb = b.pick.entrantName.toLowerCase(); }
    if (va < vb) return sortAsc ? -1 : 1;
    if (va > vb) return sortAsc ? 1 : -1;
    return 0;
  });

  document.querySelectorAll('.standings-table th[data-col]').forEach(th => {
    th.querySelector('.sort-icon').textContent =
      th.dataset.col === col ? (sortAsc ? 'â–²' : 'â–¼') : '';
  });

  renderTable(sorted, cachedScoresMap);
}

export function manualRefresh() {
  if (currentTournamentStatus === 'final') return;
  if (currentTournamentId) loadTournamentData(currentTournamentId);
}

// â”€â”€â”€ PGA Live Standings â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€

function renderPgaTable(results, scoresMap) {
  const tbody  = document.getElementById('pgaStandingsBody');
  const table  = document.getElementById('pgaStandingsTable');
  const noData = document.getElementById('pgaNoDataMsg');
  if (!tbody) return;

  if (!results.length) {
    table.classList.add('hidden');
    noData.classList.remove('hidden');
    return;
  }

  table.classList.remove('hidden');
  noData.classList.add('hidden');

  pgaCachedResults = results;
  renderPgaPoolRows('total', results);
  updatePgaPoolSortHeaders('total');
}

function renderPgaPoolRows(tab, results) {
  let tbodyId, searchId, roundNum;
  if (tab === 'total') {
    tbodyId  = 'pgaStandingsBody';
    searchId = 'pgaStandingsSearch';
  } else {
    roundNum = parseInt(tab.replace('r', ''), 10);
    tbodyId  = `pgaRoundBody${roundNum}`;
    searchId = `pgaRoundSearch${roundNum}`;
  }
  const tbody = document.getElementById(tbodyId);
  if (!tbody) return;

  // Sort results
  const sorted = [...results].sort((a, b) => {
    let va, vb;
    if (pgaPoolSortCol === 'name') {
      const na = (a.pick.realName || a.pick.entrantName || '').replace(/ \d+$/, '');
      const nb = (b.pick.realName || b.pick.entrantName || '').replace(/ \d+$/, '');
      return pgaPoolSortAsc ? na.localeCompare(nb) : nb.localeCompare(na);
    } else if (pgaPoolSortCol === 'picksName') {
      const na = a.pick.picksName || a.pick.entrantName || '';
      const nb = b.pick.picksName || b.pick.entrantName || '';
      return pgaPoolSortAsc ? na.localeCompare(nb) : nb.localeCompare(na);
    } else {
      // rank or total \u2014 sort by r.total numerically
      va = a.total;
      vb = b.total;
      if (va !== vb) return pgaPoolSortAsc ? va - vb : vb - va;
      return 0;
    }
  });

  tbody.innerHTML = sorted.map(r => {
    const rankClass   = r.rank <= 3 ? `rank-${r.rank}` : '';
    const rankDisplay = r.rank <= 3 ? ['\uD83E\uDD47', '\uD83E\uDD48', '\uD83E\uDD49'][r.rank - 1] : r.rank;
    const totalCls    = scoreClass(r.total, null);
    const rawName     = r.pick.realName || r.pick.entrantName;
    const realName    = rawName.replace(/ \d+$/, '');
    const picksName   = r.pick.picksName || r.pick.entrantName;

    const tierCells = [1,2,3,4,5,6].map(i => {
      const t = r.tierScores[`t${i}`];
      const cls     = scoreClass(t.score, t.status);
      const label   = t.status === 'cut' ? 'MC' : t.status === 'wd' ? 'WD' : formatScore(t.score, t.status);
      const top4Cls = t.isTop4 ? 'top-4-pick' : '';
      return `<td class="col-tier ${top4Cls}" title="${t.golfer}"><div class="tier-cell-card"><span class="player-name-cell">${shortName(t.golfer)}</span><small class="score-val ${cls}">${label}</small></div></td>`;
    }).join('');

    const allPlayers = [1,2,3,4,5,6].map(i => r.tierScores[`t${i}`]?.golfer || '').join(' ');

    return `
      <tr data-entry="${escapeHtml(picksName).toLowerCase()} ${escapeHtml(realName).toLowerCase()}" data-players="${escapeHtml(allPlayers).toLowerCase()}">
        <td class="col-rank ${rankClass}">${rankDisplay}</td>
        <td class="col-name">${escapeHtml(realName)}</td>
        <td class="col-name col-picks-name">${escapeHtml(picksName)}</td>
        <td class="col-total"><span class="score-val ${totalCls}">${formatScore(r.total, null)}</span></td>
        ${tierCells}
      </tr>`;
  }).join('');

  // Re-apply active search filter
  const searchInput = document.getElementById(searchId);
  if (searchInput && searchInput.value) {
    const q = searchInput.value.toLowerCase().trim();
    tbody.querySelectorAll('tr').forEach(row => {
      const entry   = row.dataset.entry   || '';
      const players = row.dataset.players || '';
      row.style.display = (!q || entry.includes(q) || players.includes(q)) ? '' : 'none';
    });
  }
}

export function pgaPoolSort(tab, col) {
  if (pgaPoolSortCol === col) {
    pgaPoolSortAsc = !pgaPoolSortAsc;
  } else {
    pgaPoolSortCol = col;
    pgaPoolSortAsc = true; // default asc for all cols including rank
  }
  if (tab === 'total') {
    if (pgaCachedResults.length) renderPgaPoolRows('total', pgaCachedResults);
  } else {
    const round = parseInt(tab.replace('r', ''), 10);
    if (pgaCachedRoundResults[round] && pgaCachedRoundResults[round].length) {
      renderPgaPoolRows(tab, pgaCachedRoundResults[round]);
    }
  }
  updatePgaPoolSortHeaders(tab);
}

function updatePgaPoolSortHeaders(tab) {
  let tableId;
  if (tab === 'total') {
    tableId = 'pgaStandingsTable';
  } else {
    const round = parseInt(tab.replace('r', ''), 10);
    tableId = `pgaRoundTable${round}`;
  }
  const table = document.getElementById(tableId);
  if (!table) return;
  table.querySelectorAll('thead th[data-sort]').forEach(th => {
    th.classList.remove('pool-sort-asc', 'pool-sort-desc');
    if (th.dataset.sort === pgaPoolSortCol) {
      th.classList.add(pgaPoolSortAsc ? 'pool-sort-asc' : 'pool-sort-desc');
    }
  });
}

async function loadPgaTournamentData(tournamentId) {
  if (pgaRefreshTimer) { clearInterval(pgaRefreshTimer); pgaRefreshTimer = null; }
  pgaCurrentTournamentId = tournamentId;

  const loadingEl = document.getElementById('pgaLoadingMsg');
  const noDataEl  = document.getElementById('pgaNoDataMsg');
  const tableEl   = document.getElementById('pgaStandingsTable');
  if (loadingEl) { loadingEl.classList.remove('hidden'); }
  if (tableEl)   { tableEl.classList.add('hidden'); }
  if (noDataEl)  { noDataEl.classList.add('hidden'); }

  try {
    const registryEntry = TOURNAMENT_REGISTRY.find(t => t.id === tournamentId && t.hardcoded);
    let tournament;
    if (registryEntry) {
      tournament = registryEntry;
      pgaCurrentTournamentStatus = tournament.status;
      updatePgaRefreshButton(tournament);
      if (loadingEl) loadingEl.classList.add('hidden');
      if (PGA_2026_TOTAL.length === 0) {
        if (noDataEl) { noDataEl.textContent = 'PGA Championship 2026 final standings coming soon.'; noDataEl.classList.remove('hidden'); }
      } else {
        renderPgaTable(PGA_2026_TOTAL, {});
        const pgaRounds = [PGA_2026_R1, PGA_2026_R2, PGA_2026_R3, PGA_2026_R4];
        pgaRounds.forEach((rd, i) => {
          pgaCachedRoundResults[i + 1] = rd;
          renderPgaRoundPanel(i + 1, rd);
        });
        loadPgaPayouts();
      }
      loadSeasonLeaderboard();
      return;
    }

    const db = getDb();
    const tSnap = await getDoc(doc(db, 'tournaments', tournamentId));
    if (!tSnap.exists()) {
      if (loadingEl) loadingEl.classList.add('hidden');
      if (noDataEl)  noDataEl.classList.remove('hidden');
      return;
    }
    tournament = { id: tSnap.id, ...tSnap.data() };
    pgaCurrentTournamentStatus = tournament.status;
    updatePgaRefreshButton(tournament);

    if (tournament.status === 'open') {
      const deadline = tournament.pickDeadline ? new Date(tournament.pickDeadline) : null;
      if (!deadline || Date.now() < deadline.getTime()) {
        if (loadingEl) loadingEl.classList.add('hidden');
        if (noDataEl) {
          const revealTime = deadline ? deadline.toLocaleString() : 'picks lock';
          noDataEl.textContent = `Standings are hidden while picks are open. Check back after ${revealTime}.`;
          noDataEl.classList.remove('hidden');
        }
        return;
      }
    }

    const picksSnap = await getDocs(
      query(collection(db, 'picks'), where('tournamentId', '==', tournamentId))
    );
    const picks = [];
    picksSnap.forEach(d => picks.push({ id: d.id, ...d.data() }));

    const scoresMap = await fetchOrRefreshScores(tournament);
    pgaCachedScoresMap = scoresMap;

    // Auto-reconcile pick names to ESPN display names (handles accents, casing, etc.)
    const reconciledPicks = reconcilePickNames(picks, scoresMap);
    const mcPenalty = tournament.mcPenalty ?? 20;

    pgaCachedResults = calculateStandings(reconciledPicks, scoresMap, mcPenalty);
    renderPgaTable(pgaCachedResults, scoresMap);

    // Render per-round standings for any round with data
    for (let round = 1; round <= 4; round++) {
      const hasRoundData = Object.values(scoresMap).some(g => g[`r${round}`] !== null && g[`r${round}`] !== undefined);
      if (hasRoundData) {
        const roundMap = buildRoundScoresMap(scoresMap, round);
        const roundResults = calculateStandings(reconciledPicks, roundMap, 0);
        pgaCachedRoundResults[round] = roundResults;
        renderPgaRoundPanel(round, roundResults);
      }
    }
    updatePgaLastUpdated();
    loadPgaPayouts();
    enrichPgaScoreboardWithPickData();
    if (loadingEl) loadingEl.classList.add('hidden');
    loadSeasonLeaderboard();  // rebuild season tab now that PGA data is available

    if (tournament.status === 'locked') {
      pgaRefreshTimer = setInterval(() => refreshPgaScores(tournament), REFRESH_INTERVAL_MS);
      if (!pgaSbRefreshTimer) {
        pgaSbRefreshTimer = setInterval(loadPgaScoreboard, REFRESH_INTERVAL_MS);
      }
    }
  } catch (err) {
    console.error('PGA standings error:', err);
    if (loadingEl) loadingEl.classList.add('hidden');
    if (noDataEl)  noDataEl.classList.remove('hidden');
  }
}

async function refreshPgaScores(tournament) {
  try {
    const fresh = await fetchEspnScores(tournament.espnEventId);
    if (Object.keys(fresh).length) {
      try { await setDoc(doc(getDb(), 'scores', tournament.id), { ...fresh, _lastUpdated: new Date() }); } catch (e) { console.warn('Score cache write failed:', e.message); }
      pgaCachedScoresMap = fresh;
      const reconciledPicks = reconcilePickNames(pgaCachedResults.map(r => r.pick), fresh);
      const mcPenalty = tournament.mcPenalty ?? 20;
      pgaCachedResults = calculateStandings(reconciledPicks, fresh, mcPenalty);
      renderPgaTable(pgaCachedResults, fresh);
      for (let round = 1; round <= 4; round++) {
        const hasRoundData = Object.values(fresh).some(g => g[`r${round}`] !== null && g[`r${round}`] !== undefined);
        if (hasRoundData) {
          const roundResults = calculateStandings(reconciledPicks, buildRoundScoresMap(fresh, round), 0);
          pgaCachedRoundResults[round] = roundResults;
          renderPgaRoundPanel(round, roundResults);
        }
      }
      updatePgaLastUpdated();
      loadPgaPayouts();
      enrichPgaScoreboardWithPickData();
      loadSeasonLeaderboard();  // keep season tab in sync during live refresh
    }
  } catch (err) {
    console.error('PGA score refresh error:', err);
  }
}

// â”€â”€â”€ Season-only tournament loader (US Open, The Open) â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
// Fetches picks + scores for a tournament that is locked or final, stores results
// in the major-specific cache, and calls loadSeasonLeaderboard to update the tab.
// Does not touch any pool-tab DOM \u2014 it only feeds the season leaderboard columns.
async function loadActiveSeasonTournamentData(major, tournamentId) {
  if (major === 'usopen' && usOpenRefreshTimer) { clearInterval(usOpenRefreshTimer); usOpenRefreshTimer = null; }
  if (major === 'theopen' && theOpenRefreshTimer) { clearInterval(theOpenRefreshTimer); theOpenRefreshTimer = null; }

  try {
    const db = getDb();
    const tSnap = await getDoc(doc(db, 'tournaments', tournamentId));
    if (!tSnap.exists()) return;
    const tournament = { id: tSnap.id, ...tSnap.data() };
    const status = tournament.status;

    if (major === 'usopen') usOpenCurrentTournamentStatus = status;
    if (major === 'theopen') theOpenCurrentTournamentStatus = status;

    // Skip if picks are still open and deadline hasn't passed
    if (status === 'open') {
      const deadline = tournament.pickDeadline ? new Date(tournament.pickDeadline) : null;
      if (!deadline || Date.now() < deadline.getTime()) return;
    }

    const picksSnap = await getDocs(query(collection(db, 'picks'), where('tournamentId', '==', tournamentId)));
    const picks = [];
    picksSnap.forEach(d => picks.push({ id: d.id, ...d.data() }));
    if (!picks.length) return;

    const scoresMap = await fetchOrRefreshScores(tournament);
    const mcPenalty = tournament.mcPenalty ?? 20;
    const results = calculateStandings(reconcilePickNames(picks, scoresMap), scoresMap, mcPenalty);

    if (major === 'usopen') usOpenCachedResults = results;
    if (major === 'theopen') theOpenCachedResults = results;

    loadSeasonLeaderboard();

    if (status === 'locked') {
      const refreshFn = async () => {
        try {
          const fresh = await fetchEspnScores(tournament.espnEventId);
          if (!Object.keys(fresh).length) return;
          try { await setDoc(doc(getDb(), 'scores', tournament.id), { ...fresh, _lastUpdated: new Date() }); } catch (e) { console.warn('Score cache write failed:', e.message); }
          const reconciledPicks = reconcilePickNames(results.map(r => r.pick), fresh);
          const updated = calculateStandings(reconciledPicks, fresh, mcPenalty);
          if (major === 'usopen') usOpenCachedResults = updated;
          if (major === 'theopen') theOpenCachedResults = updated;
          loadSeasonLeaderboard();
        } catch(e) { console.error(`${major} season refresh error:`, e); }
      };
      const timer = setInterval(refreshFn, REFRESH_INTERVAL_MS);
      if (major === 'usopen') usOpenRefreshTimer = timer;
      if (major === 'theopen') theOpenRefreshTimer = timer;
    }
  } catch(err) {
    console.error(`${major} season load error:`, err);
  }
}

function updatePgaRefreshButton(tournament) {
  const btn = document.getElementById('pgaRefreshBtn');
  if (!btn) return;
  const isFinal = tournament.status === 'final';
  btn.disabled = isFinal;
  btn.title = isFinal ? 'Tournament is final \u2014 live updates are disabled' : '';
  btn.classList.toggle('btn-disabled', isFinal);
}

function updatePgaLastUpdated() {
  const el = document.getElementById('pgaLastUpdated');
  if (el) el.textContent = `Updated ${new Date().toLocaleTimeString()}`;
}

export function pgaManualRefresh() {
  if (pgaCurrentTournamentStatus === 'final') return;
  if (pgaCurrentTournamentId) loadPgaTournamentData(pgaCurrentTournamentId);
}

// â”€â”€â”€ Player Analysis â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
export async function getPlayerAnalysisData() {
  if (!currentTournamentId) return emptyAnalysis();
  const db = getDb();

  const [picksSnap, scoresSnap] = await Promise.all([
    getDocs(query(collection(db, 'picks'), where('tournamentId', '==', currentTournamentId))),
    getDoc(doc(db, 'scores', currentTournamentId)),
  ]);

  const picks = [];
  picksSnap.forEach(d => picks.push(d.data()));
  const scores = scoresSnap.exists() ? scoresSnap.data() : {};
  const total = picks.length;
  if (!total) return emptyAnalysis();

  function scoreDisplay(name) {
    const s = scores[name];
    if (!s) return { scoreStr: '\u2014', scoreCls: '' };
    if (s.status === 'cut') return { scoreStr: 'MC', scoreCls: 'score-mc' };
    if (s.status === 'wd')  return { scoreStr: 'WD', scoreCls: 'score-mc' };
    const v = s.score ?? 0;
    return {
      scoreStr: v === 0 ? 'E' : (v > 0 ? `+${v}` : `${v}`),
      scoreCls: v < 0 ? 'score-under' : v > 0 ? 'score-over' : 'score-even',
    };
  }

  // Ownership by tier
  const ownership = [1,2,3,4,5,6].map(tierNum => {
    const key = `t${tierNum}`;
    const counts = {};
    picks.forEach(p => { const g = p[key]; if (g) counts[g] = (counts[g] || 0) + 1; });
    const golfers = Object.entries(counts)
      .map(([name, count]) => ({
        name,
        count,
        pct: Math.round(count / total * 100),
        ...scoreDisplay(name),
      }))
      .sort((a, b) => b.count - a.count);
    return { tierNum, golfers };
  });

  // Unique lineups \u2014 serialize each entry's 6 picks as a sorted key
  const lineupKeys = new Set(picks.map(p =>
    [p.t1,p.t2,p.t3,p.t4,p.t5,p.t6].map(g => g || '').join('|')
  ));
  const unique = {
    uniqueCount: lineupKeys.size,
    total,
    pct: Math.round(lineupKeys.size / total * 100),
  };

  // Contrarian picks \u2014 any golfer picked by < 10% of entries, sorted by score
  const allGolferCounts = {};
  picks.forEach(p => {
    [p.t1,p.t2,p.t3,p.t4,p.t5,p.t6].forEach(g => {
      if (g) allGolferCounts[g] = (allGolferCounts[g] || 0) + 1;
    });
  });
  const contrarian = Object.entries(allGolferCounts)
    .filter(([, c]) => c / total < 0.10)
    .map(([name, count]) => ({ name, count, pct: Math.round(count / total * 100), ...scoreDisplay(name) }))
    .sort((a, b) => {
      const sa = scores[a.name]?.score ?? 999;
      const sb = scores[b.name]?.score ?? 999;
      return sa - sb;
    })
    .slice(0, 10);

  // Most stacked \u2014 top 3 entries by lowest current total (uses cachedResults if available)
  const stacked = (cachedResults.length ? cachedResults : [])
    .slice(0, 3)
    .map(r => ({
      name: r.pick.entrantName,
      ...(() => { const v = r.total; return { scoreStr: v === 0 ? 'E' : (v > 0 ? `+${v}` : `${v}`), scoreCls: v < 0 ? 'score-under' : v > 0 ? 'score-over' : 'score-even' }; })(),
    }));

  // Tier 1 â†” Tier 2 correlations \u2014 top 3 pairings
  const pairCounts = {};
  picks.forEach(p => {
    if (p.t1 && p.t2) {
      const key = `${p.t1}||${p.t2}`;
      pairCounts[key] = (pairCounts[key] || 0) + 1;
    }
  });
  const correlations = Object.entries(pairCounts)
    .map(([key, count]) => { const [t1, t2] = key.split('||'); return { t1, t2, count }; })
    .sort((a, b) => b.count - a.count)
    .slice(0, 3);

  return { ownership, unique, contrarian, stacked, correlations };
}

function emptyAnalysis() {
  return {
    ownership: [1,2,3,4,5,6].map(tierNum => ({ tierNum, golfers: [] })),
    unique: { uniqueCount: 0, total: 0, pct: 0 },
    contrarian: [],
    stacked: [],
    correlations: [],
  };
}

export function getPgaPlayerAnalysisData() {
  if (!pgaCachedResults.length) return emptyAnalysis();
  const picks = pgaCachedResults.map(r => r.pick);
  const scores = pgaCachedScoresMap;
  const total = picks.length;

  function scoreDisplay(name) {
    const s = scores[name];
    if (!s) return { scoreStr: '\u2014', scoreCls: '' };
    if (s.status === 'cut') return { scoreStr: 'MC', scoreCls: 'score-mc' };
    if (s.status === 'wd')  return { scoreStr: 'WD', scoreCls: 'score-mc' };
    const v = s.score ?? 0;
    return {
      scoreStr: v === 0 ? 'E' : (v > 0 ? `+${v}` : `${v}`),
      scoreCls: v < 0 ? 'score-under' : v > 0 ? 'score-over' : 'score-even',
    };
  }

  const ownership = [1,2,3,4,5,6].map(tierNum => {
    const key = `t${tierNum}`;
    const counts = {};
    picks.forEach(p => { const g = p[key]; if (g) counts[g] = (counts[g] || 0) + 1; });
    const golfers = Object.entries(counts)
      .map(([name, count]) => ({ name, count, pct: Math.round(count / total * 100), ...scoreDisplay(name) }))
      .sort((a, b) => b.count - a.count);
    return { tierNum, golfers };
  });

  const lineupKeys = new Set(picks.map(p =>
    [p.t1,p.t2,p.t3,p.t4,p.t5,p.t6].map(g => g || '').join('|')
  ));
  const unique = { uniqueCount: lineupKeys.size, total, pct: Math.round(lineupKeys.size / total * 100) };

  const allGolferCounts = {};
  picks.forEach(p => {
    [p.t1,p.t2,p.t3,p.t4,p.t5,p.t6].forEach(g => { if (g) allGolferCounts[g] = (allGolferCounts[g] || 0) + 1; });
  });
  const contrarian = Object.entries(allGolferCounts)
    .filter(([, c]) => c / total < 0.10)
    .map(([name, count]) => ({ name, count, pct: Math.round(count / total * 100), ...scoreDisplay(name) }))
    .sort((a, b) => (scores[a.name]?.score ?? 999) - (scores[b.name]?.score ?? 999))
    .slice(0, 10);

  const stacked = pgaCachedResults.slice(0, 3).map(r => {
    const v = r.total;
    return { name: r.pick.picksName || r.pick.entrantName, scoreStr: v === 0 ? 'E' : (v > 0 ? `+${v}` : `${v}`), scoreCls: v < 0 ? 'score-under' : v > 0 ? 'score-over' : 'score-even' };
  });

  const pairCounts = {};
  picks.forEach(p => {
    if (p.t1 && p.t2) { const key = `${p.t1}||${p.t2}`; pairCounts[key] = (pairCounts[key] || 0) + 1; }
  });
  const correlations = Object.entries(pairCounts)
    .map(([key, count]) => { const [t1, t2] = key.split('||'); return { t1, t2, count }; })
    .sort((a, b) => b.count - a.count)
    .slice(0, 3);

  return { ownership, unique, contrarian, stacked, correlations };
}

