export async function loadPgaScoreboard() {
  const loadingEl = document.getElementById('pgaSbLoading');
  const table     = document.getElementById('pgaSbTable');
  const tbody     = document.getElementById('pgaSbBody');
  if (!table) return;

  // Clear any existing auto-refresh timer on every call
  if (pgaSbRefreshTimer) { clearInterval(pgaSbRefreshTimer); pgaSbRefreshTimer = null; }

  // Reset state on every call so stale data never persists across year switches
  table.classList.add('hidden');
  if (tbody) tbody.innerHTML = '';
  if (loadingEl) { loadingEl.textContent = 'Loading official scoreboard\u2026'; loadingEl.classList.remove('hidden'); }

  let players = [];

  if (pgaActiveYear === 2025) {
    players = PGA_2025_FIELD;
  } else {
    // Try ESPN API (2026 event 401811947)
    try {
      const res = await fetch('https://site.api.espn.com/apis/site/v2/sports/golf/leaderboard?event=401811947');
      if (res.ok) {
        const data = await res.json();
        // Capture venue for payouts header
        const evComp = data?.events?.[0]?.competitions?.[0];
        const venue = evComp?.venue;
        if (venue) {
          const city  = venue.address?.city  ?? '';
          const state = venue.address?.state ?? '';
          const vname = venue.fullName ?? '';
          const evDates = data?.events?.[0]?.date ?? '';
          pgaVenueSubtitle = [vname, city && state ? `${city}, ${state}` : (city || state)].filter(Boolean).join(' \u00B7 ');
        }
        const competitors = data?.events?.[0]?.competitions?.[0]?.competitors ?? [];
        if (competitors.length) {
          players = competitors.map(c => {
            const ls = c.linescores ?? [];
            const rounds = [1,2,3,4].map(p => {
              const ls_r = ls.find(l => l.period === p);
              if (!ls_r) return null;
              const dv = ls_r.displayValue;
              if (!dv || dv === '--' || dv === '-') return null;
              if (dv === 'E') return 0;
              const v = parseFloat(dv);
              return isNaN(v) ? null : v;
            });
            const statusTypeName = c.status?.type?.name ?? '';
            const statusLower = statusTypeName.toLowerCase();
            let dispStatus = 'Active';
            if (statusLower.includes('cut')) dispStatus = 'CUT';
            else if (statusLower.includes('wd') || statusLower.includes('withdrew')) dispStatus = 'WD';
            // Build richer status detail for active players
            let statusDetail = dispStatus;
            if (dispStatus === 'Active') {
              const thru   = c.status?.thru ?? 0;
              const period = c.status?.period ?? 0;
              const teeTime = c.teeTime ?? null;
              if (statusTypeName.includes('PLAY_COMPLETE') || thru === 18) {
                statusDetail = period ? `R${period} F` : 'F';
              } else if (thru > 0) {
                statusDetail = `Hole ${thru}`;
              } else if (teeTime) {
                try {
                  const dt = new Date(teeTime);
                  statusDetail = dt.toLocaleTimeString('en-US', {
                    hour: 'numeric', minute: '2-digit', hour12: true, timeZone: 'America/New_York'
                  }).replace(':00 ', ' ') + ' ET';
                } catch { statusDetail = 'Scheduled'; }
              } else if (statusTypeName.includes('SCHEDULED')) {
                statusDetail = 'Scheduled';
              } else {
                statusDetail = 'Active';
              }
            }
            // Compute total from available round scores \u2014 ESPN's total field shows "E" mid-round
            const completedRounds = rounds.filter(r => r !== null);
            const totalStr = c.score?.displayValue ?? 'E';
            const total = completedRounds.length > 0
              ? completedRounds.reduce((sum, r) => sum + r, 0)
              : (totalStr === 'E' ? 0 : (parseFloat(totalStr) || 0));
            return {
              pos: c.status?.position?.displayName ?? '-',
              name: c.athlete?.displayName ?? '',
              total,
              r1: rounds[0], r2: rounds[1], r3: rounds[2], r4: rounds[3],
              status: dispStatus,
              statusDetail,
            };
          }).filter(p => p.name).sort((a, b) => {
            const statusOrder = { 'Active': 0, 'CUT': 1, 'WD': 2 };
            const sa = statusOrder[a.status] ?? 0;
            const sb = statusOrder[b.status] ?? 0;
            if (sa !== sb) return sa - sb;
            return a.total - b.total;
          });
        }
      }
    } catch { /* fall through \u2014 no hardcoded 2026 fallback yet */ }
  }

  if (!players.length) {
    if (loadingEl) loadingEl.textContent = 'Scoreboard not yet available for this year.';
    return;
  }

  pgaScoreboardPlayers = players;
  enrichPgaScoreboardWithPickData();
  pgaSbSortCol = 'total';
  pgaSbSortAsc = true;
  renderPgaScoreboardRows();
  updatePgaSbSortHeaders();

  if (loadingEl) loadingEl.classList.add('hidden');
  table.classList.remove('hidden');

  // Auto-refresh scoreboard every 5 min during live tournament
  if (pgaActiveYear !== 2025 && pgaCurrentTournamentStatus === 'locked') {
    pgaSbRefreshTimer = setInterval(loadPgaScoreboard, REFRESH_INTERVAL_MS);
  }

  const searchEl = document.getElementById('pgaSbSearch');
  if (searchEl && !searchEl.dataset.wired) {
    searchEl.dataset.wired = '1';
    searchEl.addEventListener('input', () => {
      const q = searchEl.value.toLowerCase().trim();
      document.querySelectorAll('#pgaSbBody tr').forEach(row => {
        const name = row.querySelector('.pgasb-col-player')?.textContent.toLowerCase() ?? '';
        row.style.display = !q || name.includes(q) ? '' : 'none';
      });
    });
  }
}

export function pgaSbSort(col) {
  if (pgaSbSortCol === col) {
    pgaSbSortAsc = !pgaSbSortAsc;
  } else {
    pgaSbSortCol = col;
    pgaSbSortAsc = true;
  }
  renderPgaScoreboardRows();
  updatePgaSbSortHeaders();
}

export function pgaSbEntryFilter(val) {
  pgaSbSelectedEntry = val;
  renderPgaScoreboardRows();
}

function enrichPgaScoreboardWithPickData() {
  if (!pgaCachedResults.length || !pgaScoreboardPlayers.length) return;

  const pickInfoMap = {};
  for (const r of pgaCachedResults) {
    for (let i = 1; i <= 6; i++) {
      const golfer = r.pick[`t${i}`];
      if (!golfer) continue;
      if (!pickInfoMap[golfer]) pickInfoMap[golfer] = { count: 0, tiers: new Set() };
      pickInfoMap[golfer].count++;
      pickInfoMap[golfer].tiers.add(i);
    }
  }
  const total = pgaCachedResults.length;
  for (const p of pgaScoreboardPlayers) {
    const info = pickInfoMap[p.name];
    p.pickCount = info ? info.count : 0;
    p.pickPct   = info ? Math.round(info.count / total * 100) : 0;
    p.tierNums  = info ? [...info.tiers].sort((a,b) => a-b).map(n => `T${n}`) : [];
  }

  // Populate filter by real name (deduplicated, sorted)
  const sel = document.getElementById('pgaSbEntryFilter');
  if (sel) {
    const seen = new Set();
    const names = [];
    for (const r of pgaCachedResults) {
      const realName = r.pick.realName || r.pick.entrantName;
      if (!seen.has(realName)) { seen.add(realName); names.push(realName); }
    }
    names.sort((a, b) => a.localeCompare(b));
    sel.innerHTML = '<option value="">\u2014 Filter by name \u2014</option>'
      + names.map(n => `<option value="${n.replace(/"/g, '&quot;')}">${n}</option>`).join('');
    sel.value = pgaSbSelectedEntry;
  }

  renderPgaScoreboardRows();
}

function renderPgaScoreboardRows() {
  const tbody = document.getElementById('pgaSbBody');
  if (!tbody || !pgaScoreboardPlayers.length) return;

  const statusOrder = { 'Active': 0, 'CUT': 1, 'WD': 2 };
  const sorted = [...pgaScoreboardPlayers].sort((a, b) => {
    let va, vb;
    if (pgaSbSortCol === 'name') {
      return pgaSbSortAsc
        ? a.name.localeCompare(b.name)
        : b.name.localeCompare(a.name);
    } else if (pgaSbSortCol === 'status') {
      va = statusOrder[a.status] ?? 0;
      vb = statusOrder[b.status] ?? 0;
    } else if (pgaSbSortCol === 'pos') {
      va = parseFloat(a.pos) || 999;
      vb = parseFloat(b.pos) || 999;
    } else if (pgaSbSortCol === 'pickCount') {
      // Higher pick count = more owned = sort descending by default
      va = a.pickCount ?? 0;
      vb = b.pickCount ?? 0;
    } else {
      // total, r1, r2, r3, r4 \u2014 nulls sort last regardless of direction
      va = a[pgaSbSortCol] ?? (pgaSbSortAsc ? Infinity : -Infinity);
      vb = b[pgaSbSortCol] ?? (pgaSbSortAsc ? Infinity : -Infinity);
    }
    if (va !== vb) return pgaSbSortAsc ? va - vb : vb - va;
    // Secondary: active before cut/wd
    return (statusOrder[a.status] ?? 0) - (statusOrder[b.status] ?? 0);
  });

  // Build set of picked golfer names for the selected entry
  let selectedPickNames = null;
  let selectedPickTierMap = {};
  if (pgaSbSelectedEntry) {
    // Match by real name \u2014 combine picks across all entries for this person
    const entryResults = pgaCachedResults.filter(r => (r.pick.realName || r.pick.entrantName) === pgaSbSelectedEntry);
    if (entryResults.length) {
      selectedPickNames = new Set();
      for (const r of entryResults) {
        for (let i = 1; i <= 6; i++) {
          const g = r.pick[`t${i}`];
          if (g) { selectedPickNames.add(g); selectedPickTierMap[g] = i; }
        }
      }
    }
  }

  const hasPickData = sorted.some(p => p.pickCount != null);

  tbody.innerHTML = sorted.map(p => {
    const totalCls  = p.total < 0 ? 'score-under' : p.total > 0 ? 'score-over' : 'score-even';
    let rowClass = p.status === 'CUT' || p.status === 'WD' ? 'pgasb-cut' : '';
    if (selectedPickNames) {
      rowClass += selectedPickNames.has(p.name) ? ' pgasb-entry-pick' : ' pgasb-entry-dim';
    }
    const tierBadge = selectedPickNames && selectedPickTierMap[p.name]
      ? `<span class="pgasb-tier-badge">T${selectedPickTierMap[p.name]}</span>` : '';
    const ownedCell = hasPickData
      ? `<td class="pgasb-col-owned">${p.pickCount > 0 ? `${p.pickCount} <span class="pgasb-pct">(${p.pickPct}%)</span>` : '<span style="color:var(--text-muted)">\u2014</span>'}</td>`
      : '';
    const tierCell = hasPickData
      ? `<td class="pgasb-col-tier-pick">${p.tierNums?.length ? p.tierNums.join(', ') : '<span style="color:var(--text-muted)">\u2014</span>'}</td>`
      : '';
    return `
      <tr class="${rowClass.trim()}">
        <td class="pgasb-col-pos">${p.pos}</td>
        <td class="pgasb-col-player">${escapeHtml(p.name)}${tierBadge}</td>
        <td class="pgasb-col-total pgasb-col-total-border"><strong class="${totalCls}">${fmtRound(p.total)}</strong></td>
        <td class="pgasb-col-round">${fmtRoundCell(p.r1)}</td>
        <td class="pgasb-col-round">${fmtRoundCell(p.r2)}</td>
        <td class="pgasb-col-round">${fmtRoundCell(p.r3)}</td>
        <td class="pgasb-col-round">${fmtRoundCell(p.r4)}</td>
        <td class="pgasb-col-status">${p.statusDetail ?? p.status}</td>
        ${ownedCell}
        ${tierCell}
      </tr>`;
  }).join('');

  // Re-apply active search filter
  const searchEl = document.getElementById('pgaSbSearch');
  if (searchEl && searchEl.value) {
    const q = searchEl.value.toLowerCase().trim();
    tbody.querySelectorAll('tr').forEach(row => {
      const name = row.querySelector('.pgasb-col-player')?.textContent.toLowerCase() ?? '';
      row.style.display = !q || name.includes(q) ? '' : 'none';
    });
  }
}

function updatePgaSbSortHeaders() {
  document.querySelectorAll('#pgaSbTable th[data-sort]').forEach(th => {
    th.classList.remove('pgasb-sort-asc', 'pgasb-sort-desc');
    if (th.dataset.sort === pgaSbSortCol) {
      th.classList.add(pgaSbSortAsc ? 'pgasb-sort-asc' : 'pgasb-sort-desc');
    }
  });
}

